  if (s.cls === 'plant') { plant += s.words; continue; }
  if (s.words > B[s.cls]) out.push(s.cls + ' ' + s.key + ' ' + s.words + ' > ' + B[s.cls] + ' :: ' + s.text);
 }
 if (plant > B.plant) out.push('plant ' + plant + ' > ' + B.plant);
 for (const w of r.rows) if (w.words > B[w.cls]) out.push(w.cls + ' ' + w.key + ' ' + w.words + ' > ' + B[w.cls] + ' :: ' + w.text);
 return out;
};
window.textBind = (P) => {
 const out = [];
 for (const root of document.querySelectorAll('#' + P + '-card,#' + P + '-dock,.chip.' + P + '-bot,.chip.' + P + '-witness')) {
  if (!textShown(root) || !root.getClientRects().length) continue;
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  for (let t; (t = w.nextNode());) {
   const el = t.parentElement;
   if (el.closest('kbd,textarea,[data-' + P + '-meta],.' + P + '-kv') || !textShown(el)) continue;
   for (const tok of textWords(t.textContent)) if (/\d/.test(tok) && !el.closest('[data-' + P + '-binding]')) out.push('unbound "' + tok + '" in ' + el.outerHTML.slice(0, 100));
  }
 }
 return out;
};
